import json
from collections import deque

with open('/home/USER/runs/paper/qwen-h-in-glm-hpl-u1/frozen/seen-7/play/users/u026/system/state/workspace/programs/task-0f6e5a2f.json', 'r') as f:
    tasks = json.load(f)

def find_regions(grid, color):
    seen = set()
    regions = []
    rows, cols = len(grid), len(grid[0])
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and (r, c) not in seen:
                queue = deque([(r, c)])
                region_sizes = []
                seen.add((r, c))
                while queue:
                    cr, cc = queue.popleft()
                    region_sizes.append(1)
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and (nr, nc) not in seen:
                            seen.add((nr, nc))
                            queue.append((nr, nc))
                regions.append(sum(region_sizes))
    return regions

for i, tc in enumerate(tasks):
    input_grid = tc['input']
    output_grid = tc['output']

    # Get regions count for each color
    cells_by_color = {}
    for r in range(len(input_grid)):
        for c in range(len(input_grid[0])):
            col = input_grid[r][c]
            if col not in cells_by_color:
                cells_by_color[col] = 0
            cells_by_color[col] += 1

    # Find the "target color" - what does the changed region become?
    diffs = [(r, c, input_grid[r][c], output_grid[r][c]) 
             for r in range(len(input_grid)) 
             for c in range(len(input_grid[0])) 
             if input_grid[r][c] != output_grid[r][c]]

    if diffs:
        colors_changed = set(d[2] for d in diffs)
        target_colors = set(d[3] for d in diffs)

        # What's the most changed color? 
        changed_counts = {}
        for d in diffs:
            c = d[2]
            if c not in changed_counts:
                changed_counts[c] = 0
            changed_counts[c] += sum(1 for _ in [d[0], d[1]])

        most_changed = max(changed_counts, key=changed_counts.get)
        target = list(target_colors)[0]

        print(f"\nCase {i}:")
        print(f"  Most changed color: {most_changed} ({changed_counts[most_changed]} cells)")
        print(f"  Target color: {target}")
        print(f"  Cells: {cells_by_color.items()}")

