    data = json.load(f)

def get_all_regions(grid, exclude_bg=None):
    """Get all regions, exclude background if specified"""
    regions = {}
    bg = None
    if exclude_bg:
        cell_counts = Counter()
        for col in grid:
            for c in col:
                cell_counts[c] += 1
        bg = exclude_bg

    for color in set(sum(grid, [])):
        if color == bg:
            continue

        seen = set()
        region_info = []
        rows, cols = len(grid), len(grid[0])
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color and (r, c) not in seen:
                    cells = []
                    queue = deque([(r, c)])
                    seen.add((r, c))
                    while queue:
                        cr, cc = queue.popleft()
                        cells.append((cr, cc))
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and (nr, nc) not in seen:
                                seen.add((nr, nc))
                                queue.append((nr, nc))
                    region_info.append({'cells': sorted(cells), 'size': len(cells)})
        regions[color] = region_info

    return regions

def find_changed_cells(grid, grid2):
    """Return list of (row, col, original_color, new_color) where they differ"""
    changes = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != grid2[r][c]:
                changes.append((r, c, grid[r][c], grid2[r][c]))
    return changes

