print("Detailed analysis of changed regions:")
print("="*80)

for i, tc in enumerate(data):
    input_grid = tc['input']
    output_grid = tc['output']

    changes = find_changed_cells(input_grid, output_grid)
    if not changes:
        print(f"Case {i}: No changes")
        continue

    val = changes[0][2]
    target = changes[0][3]

    # Find all region sizes for val
    cells_by_region = {}
    seen_bg = set()
    for c in range(len(input_grid)):
        for r in range(len(input_grid[0])):
            if input_grid[c][r] != val:  # not background
                cp, rp = r, c
                if cp not in seen_bg:
                    seen_bg.add(cp)
                    seen_bg.add(rp)

    # Group all cells colored val into regions
    reg_seen = set()
    region_of_val = []
    for r in range(len(input_grid)):
        for c in range(len(input_grid[0])):
            if input_grid[r][c] == val and (r,c) not in reg_seen:
                cells = []
                q = deque([(r, c)])
                reg_seen.add((r, c))
                while q:
                    rc, cc = q.popleft()
                    cells.append((rc, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nc, mc = rc + dr, cc + dc
                        if 0 <= nc < len(input_grid) and 0 <= mc < len(input_grid[0]) and input_grid[nc][mc] == val and (nc, mc) not in reg_seen:
                            reg_seen.add((nc, mc))
                            q.append((nc, mc))
                region_of_val.append({'cells': cells, 'size': len(cells)})

    # Which region(s) contain changed cells?
    changed_cells_set = {(c, r) for (c, r, _, _) in changes}
    changed_regions = [reg for reg in region_of_val if any((cr, cc) in changed_cells_set for (cr, cc) in reg['cells'])]

    print(f"\nCase {i}: color {val} changed to {target}")
    print(f"  Changed cells count: {len(changed_cells_set)}")
    print(f"  All regions of {val}: {[(r['size']) for r in region_of_val]}")
    print(f"  Changed region size: {changed_regions[0]['size'] if changed_regions else 0}")
    if changed_regions:
        print(f"  Changed region cells: {changed_regions[0]['cells'][:10]}")

